mapper.select:
SELECT candidate.target_type, candidate.target_id, candidate.community_id, candidate.label, candidate.description FROM ( SELECT 'COMMUNITY' AS target_type, c.community_id AS target_id, c.community_id, NULL AS building_id, NULL AS property_unit_id, c.community_name AS label, c.address_line AS description, c.community_name AS search_text, 1 AS type_order FROM community c WHERE c.status='ACTIVE' UNION ALL SELECT 'BUILDING', b.building_id, b.community_id, b.building_id, NULL, CONCAT(c.community_name, ' · ', b.building_no, '号楼'), CONCAT('楼栋 · ', COALESCE(b.building_name, b.building_no)), CONCAT(c.community_name, ' ', b.building_no, '号楼 ', COALESCE(b.building_name, '')), 2 FROM building b JOIN community c ON c.community_id=b.community_id WHERE b.status='ACTIVE' UNION ALL SELECT 'PROPERTY', p.property_unit_id, b.community_id, b.building_id, p.property_unit_id, CONCAT(c.community_name, ' · ', b.building_no, '号楼 · ', COALESCE(bu.unit_name, CONCAT(bu.unit_no, '单元')), ' · ', p.property_no), CONCAT('房产 · ', p.property_no), CONCAT(c.community_name, ' ', b.building_no, '号楼 ', COALESCE(bu.unit_name, CONCAT(bu.unit_no, '单元')), ' ', p.property_no), 3 FROM property_unit p JOIN building_unit bu ON bu.building_unit_id=p.building_unit_id JOIN building b ON b.building_id=bu.building_id JOIN community c ON c.community_id=b.community_id WHERE p.status='ACTIVE' UNION ALL SELECT 'PERSON', per.person_id, b.community_id, b.building_id, p.property_unit_id, per.full_name, CONCAT(c.community_name, ' · ', b.building_no, '号楼 · ', p.property_no), CONCAT(per.full_name, ' ', c.community_name, ' ', b.building_no, '号楼 ', p.property_no), 4 FROM person per JOIN residence r ON r.person_id=per.person_id AND r.end_date IS NULL JOIN property_unit p ON p.property_unit_id=r.property_unit_id JOIN building_unit bu ON bu.building_unit_id=p.building_unit_id JOIN building b ON b.building_id=bu.building_id JOIN community c ON c.community_id=b.community_id WHERE per.status='ACTIVE' ) candidate WHERE 1=1 AND candidate.community_id IN #{id} AND 1=0 AND candidate.target_type=#{query.targetType}
AND candidate.community_id=#{query.parentId} AND candidate.building_id=#{query.parentId} AND candidate.property_unit_id=#{query.parentId}
AND candidate.search_text LIKE CONCAT('%', #{query.keyword}, '%') ORDER BY CASE WHEN candidate.search_text=#{query.keyword} THEN 0 WHEN candidate.search_text LIKE CONCAT(#{query.keyword}, '%') THEN 1 ELSE 2 END, candidate.type_order, candidate.label, candidate.target_id LIMIT #{query.limit}
